import { describe, expect, it } from 'vitest';
import { isBlocked } from '@/lib/moderation/blocklist';
import { hasPii } from '@/lib/moderation/pii';
import { clean, collapseRepeats, exactForm, joinSingles, looseForm, modBase } from '@/lib/moderation/normalize';
import { validateProfileInput } from '@/lib/validation/profile';
import { MUST_BLOCK, MUST_PASS, PII_NO, PII_YES } from '../parity/moderation-cases';

// 0002_hardening (security audit M4, review minor 1). The same corpus is replayed against SQL by
// supabase/tests/85_moderation_parity.sql (generated by tests/parity/moderation-sql.test.ts).
describe('moderation hardening (0002)', () => {
  it.each(MUST_BLOCK)('blocks %j', (t) => expect(isBlocked(t)).toBe(true));
  it.each(MUST_PASS)('allows %j', (t) => expect(isBlocked(t)).toBe(false));
  it.each(PII_YES)('flags PII %j', (t) => expect(hasPii(t)).toBe(true));
  it.each(PII_NO)('no PII in %j', (t) => expect(hasPii(t)).toBe(false));

  it('clean() strips the Hangul / braille / Mongolian / CGJ fillers from stored text', () => {
    expect(clean('aㅤbᅟcᅠd⠀e᠎f͏gﾠh')).toBe('abcdefgh');
    expect(clean('ㅤ')).toBeNull();
  });

  it('modBase strips leftover combining marks but keeps Vietnamese letters', () => {
    expect(modBase('Lồ̀N')).toBe('lồn');
    expect(modBase('lồn')).toBe('lồn');
    expect(modBase('Tiếng Việt có dấu')).toBe('tiếng việt có dấu');
    expect(modBase('lо̂̀n')).toBe('lồn'); // Cyrillic о + marks recomposes into Latin ồ
  });

  it('distinguishes cặc / các and buồi / buổi and keeps the exact mode diacritic-sensitive', () => {
    expect(isBlocked('cặc')).toBe(true);
    expect(isBlocked('các')).toBe(false);
    expect(isBlocked('buồi')).toBe(true);
    expect(isBlocked('buổi')).toBe(false);
    expect(looseForm('các')).toBe(' cac ');
    expect(exactForm('các')).toBe(' các ');
  });

  it('joined and collapsed passes', () => {
    expect(joinSingles(' l ồ n ')).toBe(' lồn ');
    expect(joinSingles(' a b cd e f ')).toBe(' ab cd ef ');
    expect(collapseRepeats('lồnnnn')).toBe('lồn');
    // terms with a doubled letter never take part in the collapsed pass: "180 cm" is not "cmm"
    expect(isBlocked('cao 180 cm')).toBe(false);
    expect(isBlocked('cmm')).toBe(true);
  });

  it('display name and company: PII is rejected after the blocklist check', () => {
    expect(validateProfileInput({ displayName: 'Gọi 0912345678', role: 'viewer' })).toMatchObject({ error: 'PII_NOT_ALLOWED', field: 'display_name' });
    expect(validateProfileInput({ displayName: 'Lan HR', role: 'hr', company: 'tuyendung.vn' })).toMatchObject({ error: 'PII_NOT_ALLOWED', field: 'company' });
    expect(validateProfileInput({ displayName: 'vcl', role: 'viewer' })).toMatchObject({ error: 'BLOCKED_CONTENT', field: 'display_name' });
    expect(validateProfileInput({ displayName: 'Lan HR', role: 'hr', company: 'ASP.NET Corp' })).toMatchObject({ ok: true });
  });
});
